    {
      "keystrokes": "cat > /app/src/BankBatchJob.java <<'JAVA'
import java.io.*;
import java.math.*;
import java.nio.charset.Charset;
import java.security.MessageDigest;
import java.sql.*;
import java.text.ParseException;
import java.text.SimpleDateFormat;
import java.util.*;

public class BankBatchJob {

    private static final Charset UTF8 = Charset.forName("UTF-8");
    private static final RoundingMode HALF_EVEN = RoundingMode.HALF_EVEN;

    private static final File DATA_DIR = new File("/app/data");
    private static final File OUT_DIR = new File("/app/output");

    // Must be a single literal string containing MODE=DB2 and /app/output/bankdb
    private static final String JDBC_URL = "jdbc:h2:/app/output/bankdb;MODE=DB2";

    public static void main(String[] args) throws Exception {
        ensureCleanOutputDir();

        String bizDate = readFirstLine(new File(DATA_DIR, "biz_date.txt")).trim();
        int bizDay = parseDay(bizDate);

        Map<String, FeeRule> feeRules = loadFeeRules(new File(DATA_DIR, "fee_rules.csv"));
        List<String> pivots = loadPivots(new File(DATA_DIR, "fx_pivots.csv"));
        FxBook fxBook = loadFxRates(new File(DATA_DIR, "fx_rates.csv"));

        LinkedHashMap<String, Account> accounts = loadAccounts(new File(DATA_DIR, "accounts.csv"));

        List<Txn> txns = loadTxns(new File(DATA_DIR, "transactions.csv"));

        // Precompute reversal relationships: if reversal_of points to any tx_id in file -> both rows REVERSED
        HashSet<String> allTxIds = new HashSet<String>();
        for (Txn t : txns) allTxIds.add(t.txId);
        HashSet<String> reversedTxIds = new HashSet<String>();
        for (Txn t : txns) {
            if (t.reversalOf != null && t.reversalOf.length() > 0 && allTxIds.contains(t.reversalOf)) {
                reversedTxIds.add(t.txId);
                reversedTxIds.add(t.reversalOf);
            }
        }

        // H2 DB: create and load ACCOUNTS + TXNS (all rows)
        createAndLoadDb(accounts, txns, bizDate);

        // Process txns into exceptions + per-account adjustments
        LinkedHashMap<String, BigDecimal> acctAdjSum = new LinkedHashMap<String, BigDecimal>();
        for (String acctId : accounts.keySet()) {
            acctAdjSum.put(acctId, bd("0.00"));
        }

        List<ExceptionRow> exceptions = new ArrayList<ExceptionRow>();
        int validTxs = 0;
        int skippedTxs = 0;

        HashSet<String> seenTxIds = new HashSet<String>();

        for (Txn t : txns) {
            boolean isDup = seenTxIds.contains(t.txId);
            if (!isDup) seenTxIds.add(t.txId);

            String reason = null;

            // Reasons in required precedence order
            if (reversedTxIds.contains(t.txId)) {
                reason = "REVERSED";
            } else if (t.reversalOf != null && t.reversalOf.length() > 0 && !allTxIds.contains(t.reversalOf)) {
                reason = "REVERSAL_MISSING";
            } else {
                Account acct = accounts.get(t.accountId);
                if (acct == null) {
                    // Not specified in the required list; treat as a skipped record with an explicit reason.
                    reason = "ACCOUNT_MISSING";
                } else {
                    BigDecimal fx = null;
                    if (!t.currency.equals(acct.currency)) {
                        fx = fxBook.resolveRate(t.currency, acct.currency, t.effectiveDay, pivots);
                        if (fx == null) {
                            reason = "FX_MISSING";
                        }
                    }

                    if (reason == null) {
                        if (t.effectiveDay > bizDay) {
                            reason = "AFTER_BIZ_DATE";
                        }
                    }

                    if (reason == null) {
                        if (!"POSTED".equals(t.status)) {
                            reason = t.status;
                        }
                    }

                    if (reason == null) {
                        if (isDup) {
                            reason = "DUPLICATE";
                        }
                    }

                    if (reason == null) {
                        // Valid: convert to account ccy, then fee, then add adjusted amount
                        BigDecimal amtAcc = t.amount;
                        if (fx != null) {
                            amtAcc = amtAcc.multiply(fx).setScale(10, HALF_EVEN).setScale(2, HALF_EVEN);
                        } else {
                            amtAcc = amtAcc.setScale(2, HALF_EVEN);
                        }

                        FeeRule rule = feeRules.get(acct.feePlan);
                        BigDecimal adjusted = applyFee(rule, amtAcc);

                        BigDecimal cur = acctAdjSum.get(acct.accountId);
                        if (cur == null) cur = bd("0.00");
                        acctAdjSum.put(acct.accountId, cur.add(adjusted).setScale(2, HALF_EVEN));
                        validTxs++;
                    }
                }
            }

            if (reason != null) {
                exceptions.add(new ExceptionRow(t.rowNum, t.txId, reason));
                skippedTxs++;
            }
        }

        // Build interest.csv bytes (to compute md5 from the exact bytes written)
        InterestAndTotals it = buildInterestCsv(accounts, acctAdjSum, bizDate, bizDay);

        // Write interest.csv (LF + trailing newline)
        writeBytes(new File(OUT_DIR, "interest.csv"), it.interestCsvBytes);

        String reportMd5 = md5Hex(it.interestCsvBytes);

        // Write exceptions.csv (LF + trailing newline)
        writeExceptionsCsv(new File(OUT_DIR, "exceptions.csv"), exceptions);

        // Write stats.json (single line, no newline)
        writeStatsJson(new File(OUT_DIR, "stats.json"), bizDate, accounts.size(), validTxs, skippedTxs, it.totalInterest2dp, reportMd5);

        // Insert RUN_AUDIT row
        insertRunAudit(bizDate, accounts.size(), validTxs, skippedTxs, reportMd5);
    }

    private static void ensureCleanOutputDir() throws IOException {
        if (!OUT_DIR.exists()) {
            if (!OUT_DIR.mkdirs()) throw new IOException("Failed to create /app/output");
        }
        // Clear known output files to keep reruns deterministic
        deleteIfExists(new File(OUT_DIR, "interest.csv"));
        deleteIfExists(new File(OUT_DIR, "exceptions.csv"));
        deleteIfExists(new File(OUT_DIR, "stats.json"));
        deleteIfExists(new File(OUT_DIR, "bankdb.h2.db"));
        deleteIfExists(new File(OUT_DIR, "bankdb.lock.db"));
    }

    private static void deleteIfExists(File f) {
        try {
            if (f.exists()) f.delete();
        } catch (Exception ignored) {
        }
    }

    private static LinkedHashMap<String, Account> loadAccounts(File f) throws IOException {
        LinkedHashMap<String, Account> out = new LinkedHashMap<String, Account>();
        BufferedReader br = new BufferedReader(new InputStreamReader(new FileInputStream(f), UTF8));
        try {
            String header = br.readLine();
            if (header == null) throw new IOException("accounts.csv missing header");
            String line;
            while ((line = br.readLine()) != null) {
                line = line.trim();
                if (line.length() == 0) continue;
                String[] a = splitCsv(line);
                Account acct = new Account();
                acct.accountId = a[0];
                acct.openedAt = a[1];
                acct.openedDay = parseDay(acct.openedAt);
                acct.startBalance = bd(a[2]).setScale(2, HALF_EVEN);
                acct.baseApr = bd(a[3]);
                acct.promoApr = bd(a[4]);
                acct.promoDays = Integer.parseInt(a[5]);
                acct.tierThreshold = bd(a[6]).setScale(2, HALF_EVEN);
                acct.tierApr = bd(a[7]);
                acct.currency = a[8];
                acct.feePlan = a[9];
                out.put(acct.accountId, acct);
            }
        } finally {
            br.close();
        }
        return out;
    }

    private static List<Txn> loadTxns(File f) throws IOException {
        ArrayList<Txn> out = new ArrayList<Txn>();
        BufferedReader br = new BufferedReader(new InputStreamReader(new FileInputStream(f), UTF8));
        try {
            String header = br.readLine();
            if (header == null) throw new IOException("transactions.csv missing header");
            String line;
            int rowNum = 0;
            while ((line = br.readLine()) != null) {
                line = line.trim();
                if (line.length() == 0) continue;
                rowNum++;
                String[] a = splitCsv(line);
                Txn t = new Txn();
                t.rowNum = rowNum;
                t.txId = a[0];
                t.accountId = a[1];
                t.effectiveDate = a[2];
                t.effectiveDay = parseDay(t.effectiveDate);
                t.amount = bd(a[3]).setScale(2, HALF_EVEN);
                t.currency = a[4];
                t.status = a[5];
                t.reversalOf = (a.length >= 7) ? a[6] : "";
                if (t.reversalOf == null) t.reversalOf = "";
                out.add(t);
            }
        } finally {
            br.close();
        }
        return out;
    }

    private static Map<String, FeeRule> loadFeeRules(File f) throws IOException {
        HashMap<String, FeeRule> out = new HashMap<String, FeeRule>();
        BufferedReader br = new BufferedReader(new InputStreamReader(new FileInputStream(f), UTF8));
        try {
            String header = br.readLine();
            if (header == null) throw new IOException("fee_rules.csv missing header");
            String line;
            while ((line = br.readLine()) != null) {
                line = line.trim();
                if (line.length() == 0) continue;
                String[] a = splitCsv(line);
                FeeRule r = new FeeRule();
                r.feePlan = a[0];
                r.appliesTo = a[1];
                r.flatFee = bd(a[2]).setScale(2, HALF_EVEN);
                r.pctFee = bd(a[3]);
                r.minFee = bd(a[4]).setScale(2, HALF_EVEN);
                r.maxFee = bd(a[5]).setScale(2, HALF_EVEN);
                out.put(r.feePlan, r);
            }
        } finally {
            br.close();
        }
        return out;
    }

    private static List<String> loadPivots(File f) throws IOException {
        ArrayList<String> out = new ArrayList<String>();
        BufferedReader br = new BufferedReader(new InputStreamReader(new FileInputStream(f), UTF8));
        try {
            String header = br.readLine();
            if (header == null) throw new IOException("fx_pivots.csv missing header");
            String line;
            while ((line = br.readLine()) != null) {
                line = line.trim();
                if (line.length() == 0) continue;
                String[] a = splitCsv(line);
                out.add(a[0]);
            }
        } finally {
            br.close();
        }
        return out;
    }

    private static FxBook loadFxRates(File f) throws IOException {
        FxBook book = new FxBook();
        BufferedReader br = new BufferedReader(new InputStreamReader(new FileInputStream(f), UTF8));
        try {
            String header = br.readLine();
            if (header == null) throw new IOException("fx_rates.csv missing header");
            String line;
            while ((line = br.readLine()) != null) {
                line = line.trim();
                if (line.length() == 0) continue;
                String[] a = splitCsv(line);
                int rateDay = parseDay(a[0]);
                String from = a[1];
                String to = a[2];
                BigDecimal rate = bd(a[3]);
                book.add(rateDay, from, to, rate);
            }
        } finally {
            br.close();
        }
        return book;
    }

    private static BigDecimal applyFee(FeeRule rule, BigDecimal amtAcc) {
        if (rule == null) return amtAcc.setScale(2, HALF_EVEN);

        boolean isDebit = amtAcc.compareTo(BigDecimal.ZERO) < 0;
        boolean isCredit = amtAcc.compareTo(BigDecimal.ZERO) > 0;
        boolean applies;

        if ("ALL".equals(rule.appliesTo)) {
            applies = true;
        } else if ("DEBIT".equals(rule.appliesTo)) {
            applies = isDebit;
        } else if ("CREDIT".equals(rule.appliesTo)) {
            applies = isCredit;
        } else {
            applies = false;
        }

        if (!applies) {
            return amtAcc.setScale(2, HALF_EVEN);
        }

        BigDecimal abs = amtAcc.abs();
        BigDecimal feeRaw = rule.flatFee.add(rule.pctFee.multiply(abs));
        BigDecimal fee = feeRaw.setScale(2, HALF_EVEN);
        if (fee.compareTo(rule.minFee) < 0) fee = rule.minFee;
        if (fee.compareTo(rule.maxFee) > 0) fee = rule.maxFee;

        BigDecimal adjusted = amtAcc.subtract(fee);
        return adjusted.setScale(2, HALF_EVEN);
    }

    private static InterestAndTotals buildInterestCsv(LinkedHashMap<String, Account> accounts,
                                                     Map<String, BigDecimal> acctAdjSum,
                                                     String bizDate,
                                                     int bizDay) throws IOException {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        OutputStreamWriter osw = new OutputStreamWriter(baos, UTF8);
        BufferedWriter bw = new BufferedWriter(osw);

        BigDecimal totalInterestRawSum10dp = BigDecimal.ZERO.setScale(10, HALF_EVEN);

        bw.write("account_id,biz_date,eod_balance,apr,daily_interest\n");

        // Sorted by account_id
        ArrayList<String> acctIds = new ArrayList<String>(accounts.keySet());
        Collections.sort(acctIds);

        for (String acctId : acctIds) {
            Account a = accounts.get(acctId);
            BigDecimal adj = acctAdjSum.get(acctId);
            if (adj == null) adj = bd("0.00");

            BigDecimal eod = a.startBalance.add(adj).setScale(2, HALF_EVEN);

            BigDecimal apr = a.baseApr;
            if (eod.compareTo(a.tierThreshold) >= 0) {
                apr = apr.add(a.tierApr);
            }
            int daysSince = bizDay - a.openedDay;
            if (a.promoDays > 0 && daysSince < a.promoDays) {
                apr = apr.add(a.promoApr);
            }

            BigDecimal principal = eod;
            if (principal.compareTo(BigDecimal.ZERO) < 0) principal = BigDecimal.ZERO.setScale(2, HALF_EVEN);

            BigDecimal dailyInterestRaw = principal.multiply(apr).divide(bd("365"), 10, HALF_EVEN);
            BigDecimal dailyInterestCsv = dailyInterestRaw.setScale(2, HALF_EVEN);
            totalInterestRawSum10dp = totalInterestRawSum10dp.add(dailyInterestRaw).setScale(10, HALF_EVEN);

            bw.write(a.accountId);
            bw.write(",");
            bw.write(bizDate);
            bw.write(",");
            bw.write(eod.setScale(2, HALF_EVEN).toPlainString());
            bw.write(",");
            bw.write(apr.setScale(6, HALF_EVEN).toPlainString());
            bw.write(",");
            bw.write(dailyInterestCsv.toPlainString());
            bw.write("\n");
        }

        bw.flush();

        InterestAndTotals out = new InterestAndTotals();
        out.interestCsvBytes = baos.toByteArray();
        out.totalInterest2dp = totalInterestRawSum10dp.setScale(2, HALF_EVEN);
        return out;
    }

    private static void writeExceptionsCsv(File f, List<ExceptionRow> rows) throws IOException {
        BufferedWriter bw = new BufferedWriter(new OutputStreamWriter(new FileOutputStream(f), UTF8));
        try {
            bw.write("row_num,tx_id,reason\n");
            for (ExceptionRow r : rows) {
                bw.write(Integer.toString(r.rowNum));
                bw.write(",");
                bw.write(r.txId);
                bw.write(",");
                bw.write(r.reason);
                bw.write("\n");
            }
        } finally {
            bw.close();
        }
    }

    private static void writeStatsJson(File f,
                                      String bizDate,
                                      int accounts,
                                      int validTxs,
                                      int skippedTxs,
                                      BigDecimal totalInterest2dp,
                                      String reportMd5) throws IOException {
        // single line, no newline
        String json =
                "{" +
                "\"business_date\":\"" + escapeJson(bizDate) + "\"," +
                "\"accounts\":" + accounts + "," +
                "\"valid_txs\":" + validTxs + "," +
                "\"skipped_txs\":" + skippedTxs + "," +
                "\"total_interest\":\"" + escapeJson(totalInterest2dp.setScale(2, HALF_EVEN).toPlainString()) + "\"," +
                "\"report_md5\":\"" + escapeJson(reportMd5) + "\"" +
                "}";

        OutputStream os = new FileOutputStream(f);
        try {
            os.write(json.getBytes(UTF8));
        } finally {
            os.close();
        }
    }

    private static String escapeJson(String s) {
        if (s == null) return "";
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '"') sb.append("\\\"");
            else if (c == '\\') sb.append("\\\\");
            else sb.append(c);
        }
        return sb.toString();
    }

    private static void writeBytes(File f, byte[] bytes) throws IOException {
        OutputStream os = new FileOutputStream(f);
        try {
            os.write(bytes);
        } finally {
            os.close();
        }
    }

    private static String md5Hex(byte[] bytes) throws Exception {
        MessageDigest md = MessageDigest.getInstance("MD5");
        byte[] dig = md.digest(bytes);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < dig.length; i++) {
            int b = dig[i] & 0xff;
            if (b < 16) sb.append('0');
            sb.append(Integer.toHexString(b));
        }
        return sb.toString();
    }

    private static void createAndLoadDb(LinkedHashMap<String, Account> accounts, List<Txn> txns, String bizDate) throws Exception {
        Class.forName("org.h2.Driver");
        Connection c = DriverManager.getConnection(JDBC_URL, "sa", "");
        try {
            Statement st = c.createStatement();
            try {
                // Drop if exists to ensure deterministic reruns
                safeExecute(st, "DROP TABLE RUN_AUDIT");
                safeExecute(st, "DROP TABLE TXNS");
                safeExecute(st, "DROP TABLE ACCOUNTS");

                st.execute("CREATE TABLE ACCOUNTS (" +
                        "ACCOUNT_ID VARCHAR(32) PRIMARY KEY, " +
                        "OPENED_AT DATE, " +
                        "START_BALANCE DECIMAL(18,2), " +
                        "BASE_APR DECIMAL(18,10), " +
                        "PROMO_APR DECIMAL(18,10), " +
                        "PROMO_DAYS INT, " +
                        "TIER_THRESHOLD DECIMAL(18,2), " +
                        "TIER_APR DECIMAL(18,10), " +
                        "CURRENCY VARCHAR(8), " +
                        "FEE_PLAN VARCHAR(32)" +
                        ")");

                st.execute("CREATE TABLE TXNS (" +
                        "ROW_NUM INT PRIMARY KEY, " +
                        "TX_ID VARCHAR(64), " +
                        "ACCOUNT_ID VARCHAR(32), " +
                        "EFFECTIVE_DATE DATE, " +
                        "AMOUNT DECIMAL(18,2), " +
                        "CURRENCY VARCHAR(8), " +
                        "STATUS VARCHAR(32), " +
                        "REVERSAL_OF VARCHAR(64)" +
                        ")");

                st.execute("CREATE TABLE RUN_AUDIT (" +
                        "JDBC_URL VARCHAR(2000), " +
                        "BIZ_DATE DATE, " +
                        "ACCOUNTS INT, " +
                        "VALID_TXS INT, " +
                        "SKIPPED_TXS INT, " +
                        "REPORT_MD5 VARCHAR(64)" +
                        ")");

            } finally {
                st.close();
            }

            PreparedStatement psA = c.prepareStatement(
                    "INSERT INTO ACCOUNTS (ACCOUNT_ID, OPENED_AT, START_BALANCE, BASE_APR, PROMO_APR, PROMO_DAYS, TIER_THRESHOLD, TIER_APR, CURRENCY, FEE_PLAN) VALUES (?,?,?,?,?,?,?,?,?,?)");
            try {
                for (Account a : accounts.values()) {
                    psA.setString(1, a.accountId);
                    psA.setDate(2, java.sql.Date.valueOf(a.openedAt));
                    psA.setBigDecimal(3, a.startBalance);
                    psA.setBigDecimal(4, a.baseApr);
                    psA.setBigDecimal(5, a.promoApr);
                    psA.setInt(6, a.promoDays);
                    psA.setBigDecimal(7, a.tierThreshold);
                    psA.setBigDecimal(8, a.tierApr);
                    psA.setString(9, a.currency);
                    psA.setString(10, a.feePlan);
                    psA.executeUpdate();
                }
            } finally {
                psA.close();
            }

            PreparedStatement psT = c.prepareStatement(
                    "INSERT INTO TXNS (ROW_NUM, TX_ID, ACCOUNT_ID, EFFECTIVE_DATE, AMOUNT, CURRENCY, STATUS, REVERSAL_OF) VALUES (?,?,?,?,?,?,?,?)");
            try {
                for (Txn t : txns) {
                    psT.setInt(1, t.rowNum);
                    psT.setString(2, t.txId);
                    psT.setString(3, t.accountId);
                    psT.setDate(4, java.sql.Date.valueOf(t.effectiveDate));
                    psT.setBigDecimal(5, t.amount);
                    psT.setString(6, t.currency);
                    psT.setString(7, t.status);
                    psT.setString(8, (t.reversalOf == null) ? "" : t.reversalOf);
                    psT.executeUpdate();
                }
            } finally {
                psT.close();
            }
        } finally {
            c.close();
        }
    }

    private static void insertRunAudit(String bizDate, int accounts, int validTxs, int skippedTxs, String reportMd5) throws Exception {
        Connection c = DriverManager.getConnection(JDBC_URL, "sa", "");
        try {
            Statement st = c.createStatement();
            try {
                safeExecute(st, "DELETE FROM RUN_AUDIT");
            } finally {
                st.close();
            }

            PreparedStatement ps = c.prepareStatement(
                    "INSERT INTO RUN_AUDIT (JDBC_URL, BIZ_DATE, ACCOUNTS, VALID_TXS, SKIPPED_TXS, REPORT_MD5) VALUES (?,?,?,?,?,?)");
            try {
                ps.setString(1, JDBC_URL);
                ps.setDate(2, java.sql.Date.valueOf(bizDate));
                ps.setInt(3, accounts);
                ps.setInt(4, validTxs);
                ps.setInt(5, skippedTxs);
                ps.setString(6, reportMd5);
                ps.executeUpdate();
            } finally {
                ps.close();
            }
        } finally {
            c.close();
        }
    }

    private static void safeExecute(Statement st, String sql) {
        try {
            st.execute(sql);
        } catch (SQLException ignored) {
        }
    }

    private static String readFirstLine(File f) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(new FileInputStream(f), UTF8));
        try {
            String s = br.readLine();
            if (s == null) return "";
            return s;
        } finally {
            br.close();
        }
    }

    private static BigDecimal bd(String s) {
        return new BigDecimal(s);
    }

    // yyyy-MM-dd -> day number using UTC to avoid DST surprises
    private static int parseDay(String yyyyMmDd) {
        try {
            SimpleDateFormat sdf = new SimpleDateFormat("yyyy-MM-dd");
            sdf.setLenient(false);
            sdf.setTimeZone(TimeZone.getTimeZone("UTC"));
            Date d = sdf.parse(yyyyMmDd);
            long ms = d.getTime();
            return (int) (ms / 86400000L);
        } catch (ParseException e) {
            throw new RuntimeException("Bad date: " + yyyyMmDd, e);
        }
    }

    private static String[] splitCsv(String line) {
        // Inputs are simple (no quoted commas)
        return line.split(",", -1);
    }

    private static class Account {
        String accountId;
        String openedAt;
        int openedDay;
        BigDecimal startBalance;
        BigDecimal baseApr;
        BigDecimal promoApr;
        int promoDays;
        BigDecimal tierThreshold;
        BigDecimal tierApr;
        String currency;
        String feePlan;
    }

    private static class Txn {
        int rowNum;
        String txId;
        String accountId;
        String effectiveDate;
        int effectiveDay;
        BigDecimal amount;
        String currency;
        String status;
        String reversalOf;
    }

    private static class FeeRule {
        String feePlan;
        String appliesTo;
        BigDecimal flatFee;
        BigDecimal pctFee;
        BigDecimal minFee;
        BigDecimal maxFee;
    }

    private static class ExceptionRow {
        int rowNum;
        String txId;
        String reason;
        ExceptionRow(int rowNum, String txId, String reason) {
            this.rowNum = rowNum;
            this.txId = txId;
            this.reason = reason;
        }
    }

    private static class InterestAndTotals {
        byte[] interestCsvBytes;
        BigDecimal totalInterest2dp;
    }

    private static class FxBook {
        // key: from|to -> list of (rateDay, rate)
        private final HashMap<String, ArrayList<FxRate>> rates = new HashMap<String, ArrayList<FxRate>>();

        void add(int rateDay, String from, String to, BigDecimal rate) {
            String k = key(from, to);
            ArrayList<FxRate> lst = rates.get(k);
            if (lst == null) {
                lst = new ArrayList<FxRate>();
                rates.put(k, lst);
            }
            FxRate r = new FxRate();
            r.rateDay = rateDay;
            r.rate = rate;
            lst.add(r);
        }

        BigDecimal resolveRate(String from, String to, int effectiveDay, List<String> pivots) {
            if (from.equals(to)) return BigDecimal.ONE.setScale(10, HALF_EVEN);

            // direct and reverse candidates
            RatePick direct = pickLatest(from, to, effectiveDay);
            RatePick reverse = pickLatest(to, from, effectiveDay);

            if (direct != null && reverse != null) {
                if (direct.rateDay > reverse.rateDay) {
                    return direct.rate.setScale(10, HALF_EVEN);
                } else if (reverse.rateDay > direct.rateDay) {
                    return invert(reverse.rate);
                } else {
                    // tied -> choose direct
                    return direct.rate.setScale(10, HALF_EVEN);
                }
            } else if (direct != null) {
                return direct.rate.setScale(10, HALF_EVEN);
            } else if (reverse != null) {
                return invert(reverse.rate);
            }

            // pivot search in order
            for (int i = 0; i < pivots.size(); i++) {
                String p = pivots.get(i);
                if (p.equals(from) || p.equals(to)) continue;

                BigDecimal leg1 = resolveRateNoPivot(from, p, effectiveDay);
                if (leg1 == null) continue;
                BigDecimal leg2 = resolveRateNoPivot(p, to, effectiveDay);
                if (leg2 == null) continue;

                BigDecimal combined = leg1.multiply(leg2).setScale(10, HALF_EVEN);
                return combined;
            }

            return null;
        }

        private BigDecimal resolveRateNoPivot(String from, String to, int effectiveDay) {
            if (from.equals(to)) return BigDecimal.ONE.setScale(10, HALF_EVEN);

            RatePick direct = pickLatest(from, to, effectiveDay);
            RatePick reverse = pickLatest(to, from, effectiveDay);

            if (direct != null && reverse != null) {
                if (direct.rateDay > reverse.rateDay) {
                    return direct.rate.setScale(10, HALF_EVEN);
                } else if (reverse.rateDay > direct.rateDay) {
                    return invert(reverse.rate);
                } else {
                    return direct.rate.setScale(10, HALF_EVEN);
                }
            } else if (direct != null) {
                return direct.rate.setScale(10, HALF_EVEN);
            } else if (reverse != null) {
                return invert(reverse.rate);
            }
            return null;
        }

        private RatePick pickLatest(String from, String to, int effectiveDay) {
            ArrayList<FxRate> lst = rates.get(key(from, to));
            if (lst == null) return null;

            int bestDay = Integer.MIN_VALUE;
            BigDecimal bestRate = null;

            for (int i = 0; i < lst.size(); i++) {
                FxRate r = lst.get(i);
                if (r.rateDay <= effectiveDay && r.rateDay > bestDay) {
                    bestDay = r.rateDay;
                    bestRate = r.rate;
                }
            }

            if (bestRate == null) return null;
            RatePick p = new RatePick();
            p.rateDay = bestDay;
            p.rate = bestRate;
            return p;
        }

        private BigDecimal invert(BigDecimal rate) {
            // reverse 1/rate (HALF_EVEN 10dp)
            return BigDecimal.ONE.divide(rate, 10, HALF_EVEN);
        }

        private String key(String from, String to) {
            return from + "|" + to;
        }

        private static class FxRate {
            int rateDay;
            BigDecimal rate;
        }

        private static class RatePick {
            int rateDay;
            BigDecimal rate;
        }
    }
}
