    private static class FxBook {
        // key: from|to -> list of (rateDay, rate)
        private final HashMap<String, ArrayList<FxRate>> rates = new HashMap<String, ArrayList<FxRate>>();

        void add(int rateDay, String from, String to, BigDecimal rate) {
            String k = key(from, to);
            ArrayList<FxRate> lst = rates.get(k);
            if (lst == null) {
                lst = new ArrayList<FxRate>();
                rates.put(k, lst);
            }
            FxRate r = new FxRate();
            r.rateDay = rateDay;
            r.rate = rate;
            lst.add(r);
        }

        BigDecimal resolveRate(String from, String to, int effectiveDay, List<String> pivots) {
            if (from.equals(to)) return BigDecimal.ONE.setScale(10, HALF_EVEN);

            // direct and reverse candidates
            RatePick direct = pickLatest(from, to, effectiveDay);
            RatePick reverse = pickLatest(to, from, effectiveDay);

            if (direct != null && reverse != null) {
                if (direct.rateDay > reverse.rateDay) {
                    return direct.rate.setScale(10, HALF_EVEN);
                } else if (reverse.rateDay > direct.rateDay) {
                    return invert(reverse.rate);
                } else {
                    // tied -> choose direct
                    return direct.rate.setScale(10, HALF_EVEN);
                }
            } else if (direct != null) {
                return direct.rate.setScale(10, HALF_EVEN);
            } else if (reverse != null) {
                return invert(reverse.rate);
            }

            // pivot search in order
            for (int i = 0; i < pivots.size(); i++) {
                String p = pivots.get(i);
                if (p.equals(from) || p.equals(to)) continue;

                BigDecimal leg1 = resolveRateNoPivot(from, p, effectiveDay);
                if (leg1 == null) continue;
                BigDecimal leg2 = resolveRateNoPivot(p, to, effectiveDay);
                if (leg2 == null) continue;

                BigDecimal combined = leg1.multiply(leg2).setScale(10, HALF_EVEN);
                return combined;
            }

            return null;
        }

        private BigDecimal resolveRateNoPivot(String from, String to, int effectiveDay) {
            if (from.equals(to)) return BigDecimal.ONE.setScale(10, HALF_EVEN);

            RatePick direct = pickLatest(from, to, effectiveDay);
            RatePick reverse = pickLatest(to, from, effectiveDay);

            if (direct != null && reverse != null) {
                if (direct.rateDay > reverse.rateDay) {
                    return direct.rate.setScale(10, HALF_EVEN);
                } else if (reverse.rateDay > direct.rateDay) {
                    return invert(reverse.rate);
                } else {
                    return direct.rate.setScale(10, HALF_EVEN);
                }
            } else if (direct != null) {
                return direct.rate.setScale(10, HALF_EVEN);
            } else if (reverse != null) {
                return invert(reverse.rate);
            }
            return null;
        }

        private RatePick pickLatest(String from, String to, int effectiveDay) {
            ArrayList<FxRate> lst = rates.get(key(from, to));
            if (lst == null) return null;

            int bestDay = Integer.MIN_VALUE;
            BigDecimal bestRate = null;

            for (int i = 0; i < lst.size(); i++) {
                FxRate r = lst.get(i);
                if (r.rateDay <= effectiveDay && r.rateDay > bestDay) {
                    bestDay = r.rateDay;
                    bestRate = r.rate;
                }
            }

            if (bestRate == null) return null;
            RatePick p = new RatePick();
            p.rateDay = bestDay;
            p.rate = bestRate;
            return p;
        }

        private BigDecimal invert(BigDecimal rate) {
            // reverse 1/rate (HALF_EVEN 10dp)
            return BigDecimal.ONE.divide(rate, 10, HALF_EVEN);
        }

        private String key(String from, String to) {
            return from + "|" + to;
        }

        private static class FxRate {
            int rateDay;
            BigDecimal rate;
        }

        private static class RatePick {
            int rateDay;
            BigDecimal rate;
        }
    }
