te and load ACCOUNTS + TXNS (all rows)\n        createAndLoadDb(accounts, txns);\n\n        // Process txns into exceptions + per-account adjustments\n        LinkedHashMap<String, BigDecimal> acctAdjSum = new LinkedHashMap<String, BigDecimal>();\n        for (String acctId : accounts.keySet()) {\n            acctAdjSum.put(acctId, bd(\"0.00\"));\n        }\n\n        List<ExceptionRow> exceptions = new ArrayList<ExceptionRow>();\n        int validTxs = 0;\n        int skippedTxs = 0;\n\n        HashSet<String> seenTxIds = new HashSet<String>();\n\n        for (Txn t : txns) {\n            boolean isDup = seenTxIds.contains(t.txId);\n            if (!isDup) seenTxIds.add(t.txId);\n\n            String reason = null;\n\n            // Reasons in required precedence order\n            if (reversedTxIds.contains(t.txId)) {\n                reason = \"REVERSED\";\n            } else if (t.reversalOf != null && t.reversalOf.length() > 0 && !allTxIds.contains(t.reversalOf)) {\n                reason = \"REVERSAL_MISSING\";\n            } else {\n                Account acct = accounts.get(t.accountId);\n                if (acct == null) {\n                    // Not specified in the required list; still record a skip reason\n                    reason = \"ACCOUNT_MISSING\";\n                } else {\n                    BigDecimal fx = null;\n                    if (!t.currency.equals(acct.currency)) {\n                        fx = fxBook.resolveRate(t.currency, acct.currency, t.effectiveDay, pivots);\n                        if (fx == null) {\n                            reason = \"FX_MISSING\";\n                        }\n                    }\n\n                    if (reason == null) {\n                        if (t.effectiveDay > bizDay) {\n                            reason = \"AFTER_BIZ_DATE\";\n                        }\n                    }\n\n                    if (reason == null) {\n                        if (!\"POSTED\".equals(t.status)) {\n                            reason = t.status;\n                        }\n                    }\n\n                    if (reason == null) {\n                        if (isDup) {\n                            reason = \"DUPLICATE\";\n                        }\n                    }\n\n                    if (reason == null) {\n                        // Valid: convert to account ccy, then fee, then add adjusted amount\n                        BigDecimal amtAcc10;\n                        if (fx != null) {\n                            amtAcc10 = t.amount.multiply(fx).setScale(10, HALF_EVEN);\n                        } else {\n                            amtAcc10 = t.amount.setScale(10, HALF_EVEN);\n                        }\n\n                        FeeRule rule = feeRules.get(acct.feePlan);\n                        BigDecimal adjusted = applyFee(rule, amtAcc10);\n\n                        BigDecimal cur = acctAdjSum.get(acct.accountId);\n                        if (cur == null) cur = bd(\"0.00\");\n                        acctAdjSum.put(acct.accountId, cur.add(adjusted).setScale(2, HALF_EVEN));\n                        validTxs++;\n                    }\n                }\n            }\n\n            if (reason != null) {\n                exceptions.add(new ExceptionRow(t.rowNum, t.txId, reason));\n                skippedTxs++;\n            }\n        }\n\n        // Build interest.csv bytes (to compute md5 from the exact bytes written)\n        InterestAndTotals it = buildInterestCsv(accounts, acctAdjSum, bizDate, bizDay);\n\n        // Write interest.csv (LF + trailing newline)\n        writeBytes(new File(OUT_DIR, \"interest.csv\"), it.interestCsvBytes);\n\n        String reportMd5 = md5Hex(it.interestCsvBytes);\n\n        // Write exceptions.csv (LF + trailing newline)\n        writeExceptionsCsv(new File(OUT_DIR, \"exceptions.csv\"), exceptions);\n\n        // Write stats.json (single line, no newline)\n        writeStatsJson(new File(OUT_DIR, \"stats.json\"), bizDate, accounts.size(), validTxs, skippedTxs, it.totalInterest2dp, reportMd5);\n\n        // Insert RUN_AUDIT row (must be exactly one row)\n        insertRunAudit(bizDate, accounts.size(), validTxs, skippedTxs, reportMd5);\n    }\nJAVA\n",
