      "keystrokes": "cat >> /app/src/BankBatchJob.java <<'JAVA'\n\n    private static void writeBytes(File f, byte[] bytes) throws IOException {\n        OutputStream os = new FileOutputStream(f);\n        try {\n            os.write(bytes);\n        } finally {\n            os.close();\n        }\n    }\n\n    private static String md5Hex(byte[] bytes) throws Exception {\n        MessageDigest md = MessageDigest.getInstance(\"MD5\");\n        byte[] dig = md.digest(bytes);\n        StringBuilder sb = new StringBuilder();\n        for (int i = 0; i < dig.length; i++) {\n            int b = dig[i] & 0xff;\n            if (b < 16) sb.append('0');\n            sb.append(Integer.toHexString(b));\n        }\n        return sb.toString();\n    }\n\n    private static void createAndLoadDb(LinkedHashMap<String, Account> accounts, List<Txn> txns) throws Exception {\n        Class.forName(\"org.h2.Driver\");\n        Connection c = DriverManager.getConnection(JDBC_URL, \"sa\", \"\");\n        try {\n            Statement st = c.createStatement();\n            try {\n                // Drop if exists to ensure deterministic reruns\n                safeExecute(st, \"DROP TABLE RUN_AUDIT\");\n                safeExecute(st, \"DROP TABLE TXNS\");\n                safeExecute(st, \"DROP TABLE ACCOUNTS\");\n\n                st.execute(\"CREATE TABLE ACCOUNTS (\" +\n                        \"ACCOUNT_ID VARCHAR(32) PRIMARY KEY, \" +\n                        \"OPENED_AT DATE, \" +\n                        \"START_BALANCE DECIMAL(18,2), \" +\n                        \"BASE_APR DECIMAL(18,10), \" +\n                        \"PROMO_APR DECIMAL(18,10), \" +\n                        \"PROMO_DAYS INT, \" +\n                        \"TIER_THRESHOLD DECIMAL(18,2), \" +\n                        \"TIER_APR DECIMAL(18,10), \" +\n                        \"CURRENCY VARCHAR(8), \" +\n                        \"FEE_PLAN VARCHAR(32)\" +\n                        \")\");\n\n                st.execute(\"CREATE TABLE TXNS (\" +\n                        \"ROW_NUM INT PRIMARY KEY, \" +\n                        \"TX_ID VARCHAR(64), \" +\n                        \"ACCOUNT_ID VARCHAR(32), \" +\n                        \"EFFECTIVE_DATE DATE, \" +\n                        \"AMOUNT DECIMAL(18,2), \" +\n                        \"CURRENCY VARCHAR(8), \" +\n                        \"STATUS VARCHAR(32), \" +\n                        \"REVERSAL_OF VARCHAR(64)\" +\n                        \")\");\n\n                st.execute(\"CREATE TABLE RUN_AUDIT (\" +\n                        \"JDBC_URL VARCHAR(2000), \" +\n                        \"BIZ_DATE DATE, \" +\n                        \"ACCOUNTS INT, \" +\n                        \"VALID_TXS INT, \" +\n                        \"SKIPPED_TXS INT, \" +\n                        \"REPORT_MD5 VARCHAR(64)\" +\n                        \")\");\n\n            } finally {\n                st.close();\n            }\n\n            PreparedStatement psA = c.prepareStatement(\n                    \"INSERT INTO ACCOUNTS (ACCOUNT_ID, OPENED_AT, START_BALANCE, BASE_APR, PROMO_APR, PROMO_DAYS, TIER_THRESHOLD, TIER_APR, CURRENCY, FEE_PLAN) VALUES (?,?,?,?,?,?,?,?,?,?)\");\n            try {\n                for (Account a : accounts.values()) {\n                    psA.setString(1, a.accountId);\n                    psA.setDate(2, java.sql.Date.valueOf(a.openedAt));\n                    psA.setBigDecimal(3, a.startBalance);\n                    psA.setBigDecimal(4, a.baseApr);\n                    psA.setBigDecimal(5, a.promoApr);\n                    psA.setInt(6, a.promoDays);\n                    psA.setBigDecimal(7, a.tierThreshold);\n                    psA.setBigDecimal(8, a.tierApr);\n                    psA.setString(9, a.currency);\n                    psA.setString(10, a.feePlan);\n                    psA.executeUpdate();\n                }\n            } finally {\n                psA.close();\n            }\n\n            PreparedStatement psT = c.prepareStatement(\n                    \"INSERT INTO TXNS (ROW_NUM, TX_ID, ACCOUNT_ID, EFFECTIVE_DATE, AMOUNT, CURRENCY, STATUS, REVERSAL_OF) VALUES (?,?,?,?,?,?,?,?)\");\n            try {\n                for (Txn t : txns) {\n                    psT.setInt(1, t.rowNum);\n                    psT.setString(2, t.txId);\n                    psT.setString(3, t.accountId);\n                    psT.setDate(4, java.sql.Date.valueOf(t.effectiveDate));\n                    psT.setBigDecimal(5, t.amount);\n                    psT.setString(6, t.currency);\n                    psT.setString(7, t.status);\n                    psT.setString(8, (t.reversalOf == null) ? \"\" : t.reversalOf);\n                    psT.executeUpdate();\n                }\n            } finally {\n                psT.close();\n            }\n        } finally {\n            c.close();\n        }\n    }\nJAVA\n",
