      "keystrokes": "cat >> /app/src/BankBatchJob.java <<'JAVA'\n\n    private static void insertRunAudit(String bizDate, int accounts, int validTxs, int skippedTxs, String reportMd5) throws Exception {\n        Connection c = DriverManager.getConnection(JDBC_URL, \"sa\", \"\");\n        try {\n            Statement st = c.createStatement();\n            try {\n                safeExecute(st, \"DELETE FROM RUN_AUDIT\");\n            } finally {\n                st.close();\n            }\n\n            PreparedStatement ps = c.prepareStatement(\n                    \"INSERT INTO RUN_AUDIT (JDBC_URL, BIZ_DATE, ACCOUNTS, VALID_TXS, SKIPPED_TXS, REPORT_MD5) VALUES (?,?,?,?,?,?)\");\n            try {\n                ps.setString(1, JDBC_URL);\n                ps.setDate(2, java.sql.Date.valueOf(bizDate));\n                ps.setInt(3, accounts);\n                ps.setInt(4, validTxs);\n                ps.setInt(5, skippedTxs);\n                ps.setString(6, reportMd5);\n                ps.executeUpdate();\n            } finally {\n                ps.close();\n            }\n        } finally {\n            c.close();\n        }\n    }\n\n    private static void safeExecute(Statement st, String sql) {\n        try {\n            st.execute(sql);\n        } catch (SQLException ignored) {\n        }\n    }\n\n    private static String readFirstLine(File f) throws IOException {\n        BufferedReader br = new BufferedReader(new InputStreamReader(new FileInputStream(f), UTF8));\n        try {\n            String s = br.readLine();\n            if (s == null) return \"\";\n            return s;\n        } finally {\n            br.close();\n        }\n    }\n\n    private static BigDecimal bd(String s) {\n        return new BigDecimal(s);\n    }\n\n    // yyyy-MM-dd -> day number using UTC to avoid DST surprises\n    private static int parseDay(String yyyyMmDd) {\n        try {\n            SimpleDateFormat sdf = new SimpleDateFormat(\"yyyy-MM-dd\");\n            sdf.setLenient(false);\n            sdf.setTimeZone(TimeZone.getTimeZone(\"UTC\"));\n            Date d = sdf.parse(yyyyMmDd);\n            long ms = d.getTime();\n            return (int) (ms / 86400000L);\n        } catch (ParseException e) {\n            throw new RuntimeException(\"Bad date: \" + yyyyMmDd, e);\n        }\n    }\n\n    private static String[] splitCsv(String line) {\n        // Inputs are simple (no quoted commas)\n        return line.split(\",\", -1);\n    }\n\n    private static class Account {\n        String accountId;\n        String openedAt;\n        int openedDay;\n        BigDecimal startBalance;\n        BigDecimal baseApr;\n        BigDecimal promoApr;\n        int promoDays;\n        BigDecimal tierThreshold;\n        BigDecimal tierApr;\n        String currency;\n        String feePlan;\n    }\n\n    private static class Txn {\n        int rowNum;\n        String txId;\n        String accountId;\n        String effectiveDate;\n        int effectiveDay;\n        BigDecimal amount;\n        String currency;\n        String status;\n        String reversalOf;\n    }\n\n    private static class FeeRule {\n        String feePlan;\n        String appliesTo;\n        BigDecimal flatFee;\n        BigDecimal pctFee;\n        BigDecimal minFee;\n        BigDecimal maxFee;\n    }\n\n    private static class ExceptionRow {\n        int rowNum;\n        String txId;\n        String reason;\n        ExceptionRow(int rowNum, String txId, String reason) {\n            this.rowNum = rowNum;\n            this.txId = txId;\n            this.reason = reason;\n        }\n    }\n\n    private static class InterestAndTotals {\n        byte[] interestCsvBytes;\n        BigDecimal totalInterest2dp;\n    }\nJAVA\n",
